/bin/zsh -lc "node <<'NODE'
const fs = require('node:fs');
const cp = require('node:child_process');
const fixedPoint = cp.execFileSync('git', ['rev-parse', 'HEAD'], {encoding:'utf8'}).trim();
const reason = 'Isolated subagent spawning is unavailable in this evaluation runtime; neither reviewer could be started. No inline substitute review was performed.';
const result = {
  fixed_point: {ref:'HEAD', commit:fixedPoint},
  supplied_diff:'change.diff',
  status:'unavailable',
  review_verdict:null,
  blockers:[reason],
  reviewers: [
    {axis:'Standards', agent_type:'standards_reviewer', spec:'docs/specs/496/product-spec.md'},
    {axis:'Spec', agent_type:'spec_reviewer', spec:'docs/specs/496/architecture-spec.md'}
  ].map(r => ({...r, model:'gpt-5.6-sol', reasoning_effort:'medium', status:'not_started', agent_id:null, context_id:null, verdict:null, findings:null, reason}))
};
fs.mkdirSync('.eval-output/review', {recursive:true});
const file = '.eval-output/review/contexts.json';
fs.writeFileSync(file, JSON.stringify(result, null, 2) + '\\n');
if ("'!fs.statSync(file).isFile()) throw new Error('"'Output file missing');
const parsed = JSON.parse(fs.readFileSync(file, 'utf8'));
if (parsed.reviewers.length "'!== 2 || parsed.review_verdict !== null || parsed.reviewers.some(r => r.status !== '"'not_started' || r.context_id "'!== null || r.verdict !== null)) throw new Error('"'Invalid unavailable-review record');
console.log(file + ': exists, parses, and records both reviewers as not started with no verdict');
NODE"

